#include <bits/stdc++.h>
using namespace std;
char let;int n,ans;
string sa[105]={"","","","","","","","","","","","","","","","","","","","","","","","","",""};
string s;
int main(){
	freopen("string.in","r",stdin);
	freopen("string.out","w",stdout);
	cin>>n;
	for(int i=1;i<=n;i++){
		int a;char b;
		cin>>a>>b;
		s+=sa[b-97].substr(0,a); 
	}
	for(int i=0,j=s.size()-1;i<s.size(),j>=0;i++,j--){
		if(i==j) break;
		if(s[i]!=s[j]) ans++;
	}cout<<ans;
	return 0;
}
